<?php

declare(strict_types=1);

// Only hand-written PHP. Not formatted: vendor/ and var/, generated files (config/bundles.php,
// config/reference.php, importmap.php: rewritten by Flex and `importmap:require`) and migrations
// (generated by `make:migration`; the applied ones are history).
$finder = new PhpCsFixer\Finder()
    ->in([
        __DIR__.'/src',
        __DIR__.'/tests',
    ])
    ->exclude('Migrations')
;

return new PhpCsFixer\Config()
    // Only for `declare_strict_types`, which PHP-CS-Fixer classifies as risky because it changes how
    // scalar arguments are coerced. No risky rule set (@Symfony:risky, @PHP…Migration:risky) is enabled.
    ->setRiskyAllowed(true)
    ->setRules([
        '@Symfony' => true,
        'declare_strict_types' => true,
        'array_syntax' => ['syntax' => 'short'],
        // Same as @Symfony, written out: classes, then functions, then constants, each alphabetically.
        'ordered_imports' => [
            'imports_order' => ['class', 'function', 'const'],
            'sort_algorithm' => 'alpha',
        ],
        'no_unused_imports' => true,
    ])
    ->setFinder($finder)
;
